const TABS=['collection','style','motion','app'];
export function mountLabShell({document,act,capabilities}){
 const html=document.documentElement,tabs=[...document.querySelectorAll('[data-lab-tab]')];
 function select(id,{focus=false}={}){if(!TABS.includes(id))return;html.classList.remove('lab-focus');document.querySelector('#lab-focus').setAttribute('aria-pressed','false');document.querySelector('#lab-focus').textContent='Focus';for(const tab of tabs){const active=tab.dataset.labTab===id;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;if(active&&focus)tab.focus();}for(const page of document.querySelectorAll('[data-lab-page]'))page.hidden=page.dataset.labPage!==id;}
 for(const tab of tabs){tab.onclick=()=>select(tab.dataset.labTab);tab.onkeydown=e=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=tabs.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowUp','ArrowLeft'].includes(e.key)?-1:1)+tabs.length)%tabs.length;select(tabs[next].dataset.labTab,{focus:true});};}
 for(const button of document.querySelectorAll('[data-lab-action]'))button.onclick=()=>act(button.dataset.labAction);
 const focus=document.querySelector('#lab-focus');focus.onclick=()=>{const enabled=html.classList.toggle('lab-focus');focus.setAttribute('aria-pressed',String(enabled));focus.textContent=enabled?'Show controls':'Focus';};
 const help=document.querySelector('#lab-help'),helpOpen=document.querySelector('#lab-help-open');const closeHelp=()=>{help.hidden=true;helpOpen.focus({preventScroll:true});};helpOpen.onclick=()=>{help.hidden=false;document.querySelector('#lab-help-close').focus();};document.querySelector('#lab-help-close').onclick=closeHelp;help.onkeydown=e=>{if(e.key==='Escape'){e.stopPropagation();closeHelp();}};
 for(const button of document.querySelectorAll('[data-lab-setting]'))button.onclick=()=>{document.querySelector('#settings-launcher').click();document.querySelector('[data-settings-tab="'+button.dataset.labSetting+'"]').click();};
 let pending=false;function update(){pending=false;const model=document.querySelector('#chat-model'),connected=!!model.value;document.querySelector('#lab-ai-status').textContent=connected?model.selectedOptions[0]?.textContent||model.value:'Setup needed';document.querySelector('#lab-connection-summary').textContent=connected?'Local AI selected':'Ready to explore · set up AI to chat';document.querySelector('#lab-voice-status').textContent=document.querySelector('#voice-enabled').checked?'Spoken replies on':'Spoken replies off';document.querySelector('#lab-internet-status').textContent=document.querySelector('#internet-enabled').checked?'Search enabled':'Optional search off';document.querySelector('[data-lab-action="wave"]').disabled=!capabilities().wave;}
 function schedule(){if(!pending){pending=true;queueMicrotask(update);}}
 const observer=new MutationObserver(schedule);for(const id of ['chat-model','model-caption','voice-status','setup-status'])observer.observe(document.querySelector('#'+id),{childList:true,subtree:true,characterData:true});document.addEventListener('change',schedule);window.addEventListener('pagehide',()=>observer.disconnect(),{once:true});select('collection');update();return {select,update};
}
